function fit_kundur_e123_fullsmall()
pf_init_paths; c=cases.case_kundur_two_area_classical(); pf=pfsolver.powerflow_newton_raphson(c,struct('plot_results',false,'verbose',false,'max_iter',50,'tolerance',1e-8,'enforce_q_limits',false)); M0=c.machines; ref_reim=[-0.111 3.430; -0.492 6.820; -0.506 7.020]; ref=[ref_reim, -ref_reim(:,1)./sqrt(ref_reim(:,1).^2+ref_reim(:,2).^2)];
% variables: 4 TC scales, H12/H34, lineR, Xd,Xdp,Xq,Xqp,Xpp all limited close to 1
p0=log([1.0160100221 1.2753630071 0.8474511351 0.7605308045 1.0041550548 1.0031347005 0.9842220938 1 1 1 1 1]); opts=optimset('Display','iter','MaxIter',500,'MaxFunEvals',1400,'TolX',1e-8,'TolFun',1e-12); [p,J]=fminsearch(@(p)cost(p,pf,M0,ref),p0,opts); v=exp(p); fprintf('J=%g\n',J); fprintf('v='); fprintf(' %.10f',v); fprintf('\n'); show(v,pf,M0,ref);
end
function J=cost(p,pf,M0,ref); v=exp(p); if any(v(1:4)<0.25)||any(v(1:2)>2)||any(v(3:4)>3)||any(v(5:6)<0.9)||any(v(5:6)>1.1)||v(7)<0||v(7)>3||any(v(8:12)<0.95)||any(v(8:12)>1.05); J=1e6; return; end; try; m=modes(v,pf,M0); e=[]; for k=1:3; scale=[abs(ref(k,1)) ref(k,2) ref(k,3)]; e=[e abs((m(k,:)-ref(k,:))./scale)]; end; J=max(e)^2+0.01*sum(e.^2); catch; J=1e6; end; end
function m=modes(v,pf,M0); M=M0; M.time_constants.Tpd0=M0.time_constants.Tpd0*v(1); M.time_constants.Tpq0=M0.time_constants.Tpq0*v(2); M.time_constants.Tppd0=M0.time_constants.Tppd0*v(3); M.time_constants.Tppq0=M0.time_constants.Tppq0*v(4); for kk=1:2; M.units(kk).H=M0.units(kk).H*v(5); end; for kk=3:4; M.units(kk).H=M0.units(kk).H*v(6); end; M.reactances.Xd=M0.reactances.Xd*v(8); M.reactances.Xdp=M0.reactances.Xdp*v(9); M.reactances.Xq=M0.reactances.Xq*v(10); M.reactances.Xqp=M0.reactances.Xqp*v(11); M.reactances.Xdpp=M0.reactances.Xdpp*v(12); M.reactances.Xqpp=M0.reactances.Xqpp*v(12); ssa=stability.kundur_ex126_kundur_ssa('pf',pf,'options',struct('load_model','cc_p_cz_q','machine_override',M,'line_r_scale',v(7))); lam=ssa.eigenvalues(:); osc=lam(abs(imag(lam))>.1&real(lam)<0&imag(lam)>0); [~,idx]=sort(abs(imag(osc))); osc=osc(idx); if numel(osc)<3; error('modes'); end; m=zeros(3,3); for k=1:3; m(k,:)=[real(osc(k)) imag(osc(k)) -real(osc(k))/abs(osc(k))]; end; end
function show(v,pf,M0,ref); m=modes(v,pf,M0); for k=1:3; fprintf('m%d %.10f+j%.10f z=%.10f ferr=%.5f%% zerr=%.5f%% reerr=%.5f%%\n',k,m(k,1),m(k,2),m(k,3),abs(m(k,2)-ref(k,2))/ref(k,2)*100,abs(m(k,3)-ref(k,3))/ref(k,3)*100,abs(m(k,1)-ref(k,1))/abs(ref(k,1))*100); end; end
